Use a validation middleware such as `joi`, `zod`, or `express-validator`.

**Example using `joi`:**

```js
const Joi = require('joi');

const createUserSchema = Joi.object({
  name: Joi.string().min(1).max(100).required(),
  email: Joi.string().email().required(),
});

function validateBody(schema) {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, { abortEarly: false });
    if (error) {
      return res.status(400).json({
        error: 'Validation failed',
        details: error.details.map(d => d.message),
      });
    }
    req.body = value;
    next();
  };
}

app.post('/users', express.json(), validateBody(createUserSchema), (req, res) => {
  // safe to use req.body.name, req.body.email here
  res.status(201).json({ id: 3, ...req.body });
});
```

Key principles:

- Validate every external input (query, params, body, headers, cookies).
- Enforce type, length, format, and allowlist where possible.
- Reject unexpected fields to avoid “mass assignment” problems.

